INSERT INTO questions VALUES(1,replace('Given a string,\nIt can be cool string if\n1. All Characters have same frequency\n2. If we can remove only 1 character and make it a cool string\n\nExample:\n\naaabbb -> true\nExplanation: Both a and b have same frequencies\naaabbbcccc -> true\nExplanation: a and b occur 3 times but c occurs 4 times, we can remove 1 c to make this into a cool string\naaabbbccccdddd -> false\nExplanation: a and b occur 3 times but c and d occur 4 times we''d have to remove 1 c and 1 d to make it cool string\naabbcccdddeeee -> false\nExplanation: a and b occur 2 times, c and d occur 3 times, and e occurs 4 times. We''d have to remove 1 c and 2 e''s to make it cool string','\n',char(10)),'phone','technical',X'',5139431786,'2026-08-09 11:46:41');
INSERT INTO questions VALUES(2,replace('Given an integer x, return true if x is a palindrome, and false otherwise.\n\n \n\nExample 1:\n\nInput: x = 121\nOutput: true\nExplanation: 121 reads as 121 from left to right and from right to left.\nExample 2:\n\nInput: x = -121\nOutput: false\nExplanation: From left to right, it reads -121. From right to left, it becomes 121-. Therefore it is not a palindrome.\nExample 3:\n\nInput: x = 10\nOutput: false\nExplanation: Reads 01 from right to left. Therefore it is not a palindrome.\n \n\nConstraints:\n\n-231 <= x <= 231 - 1\n \n\nFollow up: Could you solve it without converting the integer to a string?','\n',char(10)),'phone','technical',X'',5139431786,'2026-08-09 11:53:54');
INSERT INTO questions VALUES(3,replace('You will be given a grid and two points (a starting point and an ending point) along with a fuel amount. The task is to determine if it is possible to reach the ending point without running out of fuel, given that you can only travel horizontally and vertically.\n\nFollow-up: On some cells, there will be gas stations where you can refill the tank and continue the journey.','\n',char(10)),'phone','technical',X'',5139431786,'2026-08-09 12:05:00');
INSERT INTO questions VALUES(4,replace('1387. Sort Integers by The Power Value\n\nThe power of an integer x is defined as the number of steps needed to transform x into 1 using the following steps:\n\nif x is even then x = x / 2\nif x is odd then x = 3 * x + 1\nFor example, the power of x = 3 is 7 because 3 needs 7 steps to become 1 (3 --> 10 --> 5 --> 16 --> 8 --> 4 --> 2 --> 1).\n\nGiven three integers lo, hi and k. The task is to sort all integers in the interval [lo, hi] by the power value in ascending order, if two or more integers have the same power value sort them by ascending order.\n\nReturn the kth integer in the range [lo, hi] sorted by the power value.\n\nNotice that for any integer x (lo <= x <= hi) it is guaranteed that x will transform into 1 using these steps and that the power of x is will fit in a 32-bit signed integer.\n\n \n\nExample 1:\n\nInput: lo = 12, hi = 15, k = 2\nOutput: 13\nExplanation: The power of 12 is 9 (12 --> 6 --> 3 --> 10 --> 5 --> 16 --> 8 --> 4 --> 2 --> 1)\nThe power of 13 is 9\nThe power of 14 is 17\nThe power of 15 is 17\nThe interval sorted by the power value [12,13,14,15]. For k = 2 answer is the second element which is 13.\nNotice that 12 and 13 have the same power value and we sorted them in ascending order. Same for 14 and 15.\nExample 2:\n\nInput: lo = 7, hi = 11, k = 4\nOutput: 7\nExplanation: The power array corresponding to the interval [7, 8, 9, 10, 11] is [16, 3, 19, 6, 14].\nThe interval sorted by power is [8, 10, 11, 7, 9].\nThe fourth number in the sorted array is 7.\n \n\nConstraints:\n\n1 <= lo <= hi <= 1000\n1 <= k <= hi - lo + 1','\n',char(10)),'phone','technical',X'',5139431786,'2026-08-09 12:07:50');
INSERT INTO questions VALUES(5,replace('There is a Welsh dictionary lets say the order in the dictionary is\n\nalphabets = ["a", "b", "c", "ch", "d", "dd", "e", "f", "ff", "g", "ng", "h", "i", "l", "ll", "m", "n", "o", "p", "ph", "r", "rhe", "s", "t", "th", "u", "w", "y"]\n\n Note that the characters in the welsh dictionary are either single english  character or double. so whenever you check for charcters in the words, give priority for the double characters (for eg in the word "ddb", the charcaters you consider should be "dd" and "b" not "d", "d", "b") and then u will be given a list of words like for example inputs = ["ddr", "nah", "dea", "dd", "ngah"].  You will need to sort the list of words and return the sorted list\n\nFollow up: What if the alphabet has elements with more that two characters like\n\nalphabets = ["a", "beeee", "c", "ch", "d", "dd", "e", "f", "ff", "g", "ng", "h", "i", "l", "ll", "m", "n", "o", "p", "phe", "r", "rhe", "s", "t", "th", "u", "w", "y"]','\n',char(10)),'1','technical',X'',5139431786,'2026-08-09 12:11:49');
INSERT INTO questions VALUES(6,replace('name, amount, time, location\nAnne, 100, 0, NY\nAnne, 100, 30, LA\nAnne, 50000, 50, LDN\n\noutput\n\n1. If the amount is greater than 1000, then mark the transaction as potentially fraudulent.\n2. If a transaction with the same name occurs within 60 minutes in a different location, then mark both transactions as potentially fraudulent.\n\ntransactions = [[Anne, 100, 0, NY], [Anne, 100, 30, LA]]','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 12:14:28');
INSERT INTO questions VALUES(7,replace('When ever you visit a website you save it in your History and when you''re asked for the history you are to print the history form the recently visited to the last visited.\n\nexample:\nbbc.com\nbloomberg.com\nmsn.com\nbloomberg.com\n\nwhen asked for history:\nbloomberg.com\nmsn.com\nbbc.com\n\nNote: for duplicate website you print the recent\n\ntip:it''s like LRU cache but there is no limit','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 12:15:30');
INSERT INTO questions VALUES(8,replace('When ever you visit a website you save it in your History and when you''re asked for the history you are to print the history form the recently visited to the last visited.\n\nexample:\nbbc.com\nbloomberg.com\nmsn.com\nbloomberg.com\n\nwhen asked for history:\nbloomberg.com\nmsn.com\nbbc.com\n\nNote: for duplicate website you print the recent\n\ntip:it''s like LRU cache but there is no limit','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 12:16:13');
INSERT INTO questions VALUES(9,replace('Design Autocomplete system. \n\nThere is row data like, for example, date = [[''I'', ''am'', ''lost''], [''lost'', ''i'', ''am''], [''i'', ''gain'', ''waight'']]. First, you need to train the model so that if we write one word, it recommends the next one. If a user enters ''I'', it should recommend ''am'' or ''gain''. However, it must recommend the one with the highest frequency. So for ''i'' -> (am, 2) & (gain, 1), the recommendation will be ''am''. \n\ninterviewee''s note: I didn''t write the full code; rather, we took time to talk about the system, and he was very supportive.','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 12:19:08');
