INSERT INTO questions VALUES(11,replace('She showed me the Bloomberg Terminal and explained that data is coming from an external API, including buy prices, sell prices, and trade prices (where buy equals sell). Therefore, we need to display the most recent data in real time for the user.\n\nFollow-up questions:\n1. For each functional and non-functional requirement I choose, she asked why I chose them, the reasons, and the trade-offs.\n2. What if the user wants to view their history by selecting a custom date?\n\nTips: On all rounds, I try to ask as many questions as I can—3 to 6 questions—about what they talk about when they introduce themselves.','\n',char(10)),'3','technical',X'',5139431786,'2026-08-09 12:21:44');
