INSERT INTO questions VALUES(91,replace('You are given a string s consisting of any characters. Your task is to repeatedly remove any substring that contains three or more consecutive identical characters.\n\nAfter each removal, the remaining parts of the string are concatenated together, and the process continues until no such substring exists.\n\nReturn the final string after all possible removals.\n\n\nExample 1:\nInput: s = "aabbbbc"\nOutput: "aac"\n\nExample 2:\nInput: s = "aabbbbac"\nOutput: "c"','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 14:02:18');
INSERT INTO questions VALUES(92,replace('"""\nImplement a module for a CCTV cameras by a highway.\nIt''s supposed to log traffic events (a car passes by) and then provide aggregate on-demand statistics about the traffic passed so far.\n"""\n\n\nfrom datetime import datetime\nfrom collections import defaultdict\nclass TrafficMonitor:\n   def __init__(self):\n       self.vehicle_store = []\n      \n   def onVehiclePassed(self, vehicle_type):\n       # log traffic events (a car passes by)\n       # current time datetime.now()\n       # (vehicle_type, timestamp)\n      \n       current_time = datetime.now()\n       self.vehicle_store.append((vehicle_type, current_time))\n      \n       # TC = O(1)\n       # SC = O(n)\n       ...\n\n\n   def printStatistics(self, N, start_time, end_time):\n      # [e1 <=, e2 <=, e3 <=, e4 <=, e5 <=, e6 <=, e7] - Binary Search on this event array using bisect_left(start_time) bisect_right(end_time) since events happen sequentially they are sorted\n\n\n       frequency = defaultdict(int)\n       for vehicle_type, timestamp in self.vehicle_store:\n           if start_time <= timestamp <= end_time:\n               frequency[vehicle_type] += 1\n      \n       store = []\n       for vehicle_type, frequency in frequency.items():\n           store.append(vehicle_type, frequency)\n      \n       store.sort(key=lambda x : -x[1]) # sort in reverse by timestamp\n      \n       for vehicle_type, frequency in store[:N]:\n           print(vehicle_type, ":", frequency)\n          \n       # TC = O(events) + O(n log n) -> O(n log N) using min-heap\n   # where n is the number of types of vehicle\n       # SC = O(n)\n      \n       """\n       Prints top N most frequent vehicle types that passed between startTime and endTime.\n       E.g if between 9:00 and 10:00 we had 500 Sedans, 5 motorcycles, 200 SUVs and 50 trucks, the stdout would contain:\n           - for N=1\n               Sedan: 500\n\n\n           - for N=2\n               Sedan: 500\n               SUV: 200\n\n\n           - etc\n       """\n\nThe follow up focused on some optimizations.\nthe first optimization was to use a min-heap to get the top N items instead of sorting the entire list.\nThe second optimization was for event processing  we could use binary search\nAnother follow up question was about how we can guarantee that binary search works on the events list. the answer is that events occur sequentially, so the list is already ordered by time','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 14:04:38');
