INSERT INTO questions VALUES(94,replace('Two sum, but instead of getting the sum find two nums that their difference gives target.\nWhat if we reorder the array?(it matters actually)\nHe also asks How does hashing works in set and hash map','\n',char(10)),'1','technical',X'',5139431786,'2026-08-09 14:05:26');
INSERT INTO questions VALUES(95,replace('Assume an operating system\nThere are process and process can have children, grandchildren ... \nEach process has a parent process except one of the process which you can assume as the root process\nA process has an information about its children but not its parent\n\nProcesses can get aborted and when a process gets aborted all its descendants get aborted along with it \n\nAnd there is a log system that logs all the processes that are aborted\nAnd you are tasked to find the initial process that caused all the processes to abort\n\nFor example the log might input \n[id: 1, children: [2, 3],\nid: 2, children: [4],\nid: 3, children:[],\nid: 4, children: []]\n\n    1\n/      \\n2      3\n|\n4\n\nYou are tasked to find the one process that caused all the process to abort \n\nIn this case ans = 1\n\nFollow up what if a process has multiple parents, or cycles in processes in which case you have to return None or stop your computation','\n',char(10)),'1','technical',X'',5139431786,'2026-08-09 14:05:49');
INSERT INTO questions VALUES(96,replace('You are on a desert given by an m * n matrix containing characters ''.'', ''c'', ''o''. The c is your car''s position and ''o'' is an oasis you want to get to with your given fuel. The question is can you make it to the oasis. \n\nNext up, he added obstacles to the matrix given by ''r''. So a particular example would be:\n[\n  [''.'',''.'', ''c''],\n  [''.'',''r'', ''r''],\n  [''.'',''.'', ''o'']\n]','\n',char(10)),'1','technical',X'',5139431786,'2026-08-09 14:06:24');
INSERT INTO questions VALUES(97,replace('An analyst at your work has implemented a tool to help them with a step in a data ingestion pipeline. This tool has greatly increased their productivity, and they have been sharing it with others. You, as a software Engineer at Bloomberg, have been asked to formalise this tool into a service. My role is as your Colleague and Mentor with experience in this team.\012\012The ingestion pipeline takes data files are sent from many external providers by email. They are expected to come in as text files with one word per line, with anagrams grouped onto consecutive lines. The file name is a unique identifier for the provider and a date (e.g. GS1234.20230525.txt). If the file content is not correct then an error alert email is sent to the data analysts and they need to repair the file so it can be ingested, plus feedback to the data provider so they hopefully submit it correctly in the future. Corrected files are placed in a network folder that is monitored by the ingestion pipeline.\012\012The tool the analyst developed takes a text file with a series of words, one per line. It transforms this file into a new one where the words are grouped by anagram. The files come in varying sizes, and with varying priorities. The number of files able to be corrected at the moment is limited by the number of analysts, however the backlog is increasing very quickly.\012\012# input: a series of words, one per line\012# output: these words with any anagrams grouped on consecutive lines\012#\012# sample in:\012# dog\012# oak\012# god\012#\012# sample out:\012# oak\012# god\012# dog\012#\012# sample out:\012# dog\012# god\012# oak\012\012\012The analyst has implemented the following logic:\012\012// Open file for input\012// Create a HASHMAP/HASHTABLE with a string key, and a list of strings as the value\012// While there is a new line in the file\012    // Read a line into a string VALUE\012    // hash the value to give a KEY\012    // add the KEY, VALUE pair to the HASHMAP\012// Close the input file\012// Open an output file for writing\012// for each KEY in the HASHMAP\012    // for each string VALUE in the value list\012        // Write the VALUE to the output file\012// Close the output file\012\012\012C:> python convertfile.py in.txt out.txt\012C:> cp out.txt z:\next_stage\input_files\','\012',char(10)),'3','technical',X'',5139431786,'2026-08-09 14:07:09');
