INSERT INTO questions VALUES(101,replace('https://leetcode.com/problems/longest-substring-without-repeating-characters/description\n\nGiven a string s, find the length of the longest substring without duplicate characters.\n\n \n\nExample 1:\n\nInput: s = "abcabcbb"\nOutput: 3\nExplanation: The answer is "abc", with the length of 3. Note that "bca" and "cab" are also correct answers.\nExample 2:\n\nInput: s = "bbbbb"\nOutput: 1\nExplanation: The answer is "b", with the length of 1.\nExample 3:\n\nInput: s = "pwwkew"\nOutput: 3\nExplanation: The answer is "wke", with the length of 3.\nNotice that the answer must be a substring, "pwke" is a subsequence and not a substring.\n \n\nConstraints:\n\n0 <= s.length <= 105\ns consists of English letters, digits, symbols and space','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 14:10:09');
