INSERT INTO questions VALUES(116,replace('I was asked me to implement the function collatz, which is \n- If x is even, divide it by 2\n- If x is odd, multiply by 3 and add 1\n\nThe first task was to calculate the number of steps required for a given x to reach 1.\n\nThen he asked few followups:\n\n1 . What are the drawbacks of a recursive solution, and could it be converted to an iterative one?\n\n2. How would you optimize if there are multiple calls to collatz? (i  store the answer for every call)\n\n3. then he asked How could you store all numbers reached during the calculation, so for example, for 10 → 5 → 16 → 8 → 4 → 2 → 1, the memory should have {10:6, 5:4, 16:7, 8:3, 4:2, 2:1, 1:0} to speed up future queries.','\n',char(10)),'1','technical',X'',5139431786,'2026-08-09 14:19:24');
