INSERT INTO questions VALUES(119,replace('You are given a chess board and add_bishop(row, col) is called on it. you will add a bishop on that cell. But you have to return false if there are other bishops along the two diagonals passing that cell.\n\nFollow up–instead of returning boolean return the cell of the existing bishop','\n',char(10)),'1','technical',X'',5139431786,'2026-08-09 14:21:37');
INSERT INTO questions VALUES(120,replace('I was caught totally off guard, it is not the typical system design question you''d expect\nIt was OOP design question - like writing class, methods, attributes, coding in editor\nIt was not what I expected and I was confused a bit but here is the problem\nYou have an AppStore where applications are listed just like Google Play Store or Apple App Store\nYour current app store is currently being used by users and working fine but as the user base increased, its performance started degrading, so you have to look in to the class design and find the bottleneck and improve it, there are also new functionality that are yet to be implemented\nBut while achieving this, the interface shouldn''t change that much since there are many users relying in the current architecture i.e. it should be backward compatible while adding the new functionalities and increasing its performance and improving it''s scalability \nYou are initially given the original class implementations and templates\nThere are two classes AppEntry which is a class definition for the application it self\nHas attribute app_id, app_name, publisher_id, publisher_name\n\nThe second class AppStore which is the app store it self that stores the apps inventory\nIt has only an inventory dictionary that is going to store all the apps in the app store app_id: AppEntry obj\n\nThere are getter and setter methods in each class\n\nYou can add new classes new methods any thing you like as long as you don''t break existing interfaces and achieve scalability \n\nThe major bottleneck I identified was inside the AppStore class, there is a method get_publisher_name(pub_id) given the publisher''s ID return it''s name, in the current this is achieved by going through all the apps in the inventory and making by pub_id then returning the pub_name\n\nThe new functionalities to be added are \nget_all_published_app(pub_id) - return all apps published by a specific publisher\nrename_publiser(pub_id) - rename a publisher given pub id\n\nThe method that caused me trouble was inside the AppEntry class\nThere is a method called get_publisher_name which is used to return the publisher''s name that published the app','\n',char(10)),'3','technical',X'',5139431786,'2026-08-09 14:22:15');
INSERT INTO questions VALUES(121,replace('a lottery system with three methods:\n\naddParticipant to the lottery\ndeleteParticipant from the lottery\ngetRandomParticipant from the lottery\n\nFollow up:\nwhat if there were duplicates and how can we increase the chances of a participant being selected based on the frequency.','\n',char(10)),'2','technical',X'',5139431786,'2026-08-09 14:22:42');
INSERT INTO questions VALUES(122,replace('A note taking app with the following functionalities:\n\n- creating, viewing, editing and deleting a note\n- sharing a note with others, with different access levels (edit, view etc...)\n- offline functionality, and being able to sync changes with other device.\n- the file size is also not fixed, might be large or small. (object storage could be a viable solution here)\n\n\n- He wanted to emphasize on the offline feature, and the note sharing feature. he also asked how a user would be notified when a note has been shared to him/her,  so explaining how a notification system (in app notification) works was a bit of a hassle here. \n\n- generally we started with the high level design and explained the deep dives as the interview went on.\n\nthe interview was basically designing Drop Box.\n\nhttps://www.hellointerview.com/learn/system-design/problem-breakdowns/dropbox','\n',char(10)),'3','technical',X'',5139431786,'2026-08-09 14:23:38');
